const express = require('express');
const Influx = require('influx');
const pg = require('../pgClient');

const app = express();
const influx = new Influx.InfluxDB({
  host: process.env.INFLUX_HOST,
  database: 'fleet_tracking'
});

app.get('/api/fleet/gps-history', async (req, res) => {
  const { vin, startTime } = req.query;
  if (!vin) {
    return res.status(400).json({ error: 'VIN is required' });
  }

  // Validate that the VIN belongs to the authenticated user's fleet organization
  const vehicle = await pg.query(
    'SELECT vin FROM fleet_vehicles WHERE vin = $1 AND organization_id = $2',
    [vin, req.user.organizationId]
  );
  if (vehicle.rows.length === 0) {
    return res.status(404).json({ error: 'Vehicle not found in organization fleet' });
  }

  try {
    const records = await influx.query(
      `SELECT latitude, longitude, speed FROM vehicle_gps WHERE vin = '${vin}' AND time >= '${startTime || 'now() - 6h'}'`
    );
    return res.json({ vin, history: records });
  } catch (err) {
    return res.status(500).json({ error: 'Failed to retrieve GPS history' });
  }
});

module.exports = app;
